import base64, zlib, os
F = {}
F['supabase/migrations/037_coach_dashboard_new_clients.sql'] = ''
F['src/lib/coachMetrics.ts'] = ''
F['src/lib/adminHealth.ts'] = ''
F['src/components/admin/AdminPlatform.tsx'] = ''
F['src/tests/v2/CoachMetrics.test.ts'] = ''
F['scripts/sim/ts-checks.mjs'] = ''
for p, d in F.items():
    os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, 'wb').write(zlib.decompress(base64.b64decode(d)))
    print('wrote', p)
print('Done.')